const q = "appProperties has { key='jarvis_brief' and value='" + key + "' } and trashed = false";
return [{ json: { brief: true, key: key, ordner: ordner, name: name, html: html, task_id: v.task_id, action_id: v.action_id, q: q } }];

// CR-16c: Google Doc aus HTML (Drive-Import), mehrteilige Anfrage mit Metadaten und Merkzeichen jarvis_brief.
const j = $('Brief vorbereiten').first().json;
const B = 'jarvis_brief_' + j.key;
const meta = { name: j.name, mimeType: 'application/vnd.google-apps.document', parents: [j.ordner], appProperties: { jarvis_brief: j.key, jarvis_task: j.task_id } };
const body = Buffer.concat([
  Buffer.from('--' + B + '
Content-Type: application/json; charset=UTF-8

' + JSON.stringify(meta) + '
--' + B + '
Content-Type: text/html; charset=UTF-8

', 'utf8'),
  Buffer.from(j.html, 'utf8'),
  Buffer.from('
--' + B + '--
', 'utf8')]);
return [{ json: { boundary: B }, binary: { mp: { data: body.toString('base64'), mimeType: 'multipart/related; boundary=' + B, fileName: 'brief_anfrage.txt' } } }];

// CR-16c: PDF-Fassung des Briefs neben dem Google Doc ablegen (gleiches Merkzeichen).
const j = $('Brief vorbereiten').first().json;
const it = $input.first();
if (!it || !it.binary || !it.binary.pdf) throw new Error('PDF-Export lieferte keine Datei');
const pdf = await this.helpers.getBinaryDataBuffer(0, 'pdf');
if (pdf.length < 500 || pdf.slice(0, 5).toString('latin1') !== '%PDF-') throw new Error('PDF-Export ungültig');
const B = 'jarvis_pdf_' + j.key;
const meta = { name: j.name + '.pdf', mimeType: 'application/pdf', parents: [j.ordner], appProperties: { jarvis_brief: j.key, jarvis_task: j.task_id } };
const body = Buffer.concat([
  Buffer.from('--' + B + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + JSON.stringify(meta) + '\r\n--' + B + '\r\nContent-Type: application/pdf\r\n\r\n', 'utf8'),
  pdf,
  Buffer.from('\r\n--' + B + '--\r\n', 'utf8')]);
return [{ json: { boundary: B }, binary: { mp: { data: body.toString('base64'), mimeType: 'multipart/related; boundary=' + B, fileName: 'pdf_anfrage.txt' } } }];

// CR-16c: Ergebnisnachweis = von Google Drive gelieferte Datei-IDs (neu angelegt oder per Merkzeichen wiedergefunden).
const j = $('Brief vorbereiten').first().json;
let doc = null; let pdf = null; let neu = false;
try { neu = $('Brief anlegen').isExecuted === true; } catch (x) { neu = false; }
if (neu) { doc = $('Brief anlegen').first().json; pdf = $('PDF anlegen').first().json; }
else {
  const f = (($('Brief suchen').first().json || {}).files) || [];
  doc = f.filter(function (x) { return x.mimeType === 'application/vnd.google-apps.document'; })[0] || null;
  pdf = f.filter(function (x) { return x.mimeType === 'application/pdf'; })[0] || null;
}
if (!doc || !/^[A-Za-z0-9_-]{10,200}$/.test(String(doc.id || ''))) throw new Error('Google Drive lieferte keine Dokument-ID');
const pdfOk = !!(pdf && /^[A-Za-z0-9_-]{10,200}$/.test(String(pdf.id || '')));
const brief = { state: 'done', key: j.key, name: j.name, doc_id: doc.id, doc_link: 'https://docs.google.com/document/d/' + doc.id + '/edit',
  pdf_id: pdfOk ? pdf.id : null, pdf_link: pdfOk ? 'https://drive.google.com/file/d/' + pdf.id + '/view' : null,
  erstellt_at: new Date().toISOString(), nachweis: neu ? 'drive_create_response' : 'drive_appproperty_search', action_id: j.action_id };
return [{ json: { brief: brief, p64: Buffer.from(JSON.stringify({ task_id: j.task_id, brief: brief }), 'utf8').toString('base64') } }];

// CR-16c: Briefdokument fehlgeschlagen – Outlook-Entwurf bleibt gültig, Fehler wird am Auftrag vermerkt.
const j = $('Brief vorbereiten').first().json;
const f = $input.first().json || {};
let m = f.error;
if (m && typeof m === 'object') m = m.message || m.description || JSON.stringify(m);
m = String(m || f.message || 'unbekannter Fehler').replace(/\s*\[line [0-9]+\]\s*$/, '').slice(0, 200);
const brief = { state: 'failed', fehler: 'Das Briefdokument konnte nicht erstellt werden (' + m + '). Bitte «Anpassen» und «Entwurf neu fassen».', at: new Date().toISOString(), action_id: j.action_id };
return [{ json: { brief: brief, p64: Buffer.from(JSON.stringify({ task_id: j.task_id, brief: brief }), 'utf8').toString('base64') } }];

// CR-16c: Antwort des Auftrags um das Briefdokument ergänzen.
const ab = $('Abschluss melden').first().json || {};
const antwort = Object.assign({}, ab.antwort || {});
let brief = null; let warn = null; let gespeichert = true;
try { if ($('Brief merken').isExecuted) brief = $('Brief merken').first().json.brief; } catch (x) { brief = null; }
try { if (!brief && $('Brieffehler').isExecuted) brief = $('Brieffehler').first().json.brief; } catch (x) { brief = brief; }
try { const bv = $('Brief vorbereiten').first().json; if (bv && bv.warnung) warn = bv.warnung; } catch (x) { warn = null; }
try { if ($('Brief speichern').isExecuted) { const r = $('Brief speichern').first().json || {}; gespeichert = !r.error && Number(r.aktualisiert) === 1; } } catch (x) { gespeichert = gespeichert; }
if (antwort.auftrag && brief) antwort.auftrag = Object.assign({}, antwort.auftrag, { brief: brief });
let h = antwort.hinweis || '';
if (brief && brief.state === 'done') h += ' Der Brief liegt als Google Doc' + (brief.pdf_id ? ' und PDF' : '') + ' im Entwurfsordner.' + (gespeichert ? '' : ' (Verknüpfung am Auftrag nicht gespeichert.)');
else if (brief && brief.state === 'failed') h += ' ' + brief.fehler;
else if (warn) h += ' ' + warn;
antwort.hinweis = h.trim();
return [{ json: { antwort: antwort } }];
